def magic_square_test(matrix):
    n = len(matrix)
    if n != 4:
        return False

    # Calculate the sum of the first row
    total_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != total_sum:
            return False

    # Check if all columns have the same sum
    for col in range(n):
        column_sum = sum(matrix[row][col] for row in range(n))
        if column_sum != total_sum:
            return False

    # Check if both diagonals have the same sum
    diagonal_sum1 = sum(matrix[i][i] for i in range(n))
    diagonal_sum2 = sum(matrix[i][n-i-1] for i in range(n))
    if diagonal_sum1 != total_sum or diagonal_sum2 != total_sum:
        return False

    return True
```

